import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import type { CatalogSnapshot } from '@cuccut/protocol';

/**
 * Build-time catalog snapshot (agent-surface design §2.3): `--help`, `help <command>` and `spec` derive from it when not connected to the Runtime. Generated by
 * `tools/catalog-snapshot.ts` (`npm run build:catalog`), not checked into git. When connected to the Runtime, command execution always follows `catalog.list`.
 *
 * It is read by path rather than a static import: the CLI still loads when the snapshot is absent; only the offline help then gives the generating command.
 */
export const SNAPSHOT_FILE = fileURLToPath(new URL('../generated/catalog.json', import.meta.url));

/** The command that generates the snapshot (shown when the snapshot is missing). */
export const SNAPSHOT_COMMAND = 'npm run build:catalog';

export function loadSnapshot(file = SNAPSHOT_FILE): CatalogSnapshot | null {
  let text: string;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch {
    return null;
  }
  const parsed = JSON.parse(text) as CatalogSnapshot;
  return Array.isArray(parsed.tools) && typeof parsed.interfaceVersion === 'string' ? parsed : null;
}
